entry.content:
前置无聊开个新坑，最近学校在学 C++ ，那么这边也跟进一下实操分析。主要还是当备忘录使的，[保存回家路线，防止迷路（bushi）]
本蒟蒻 C++ 其实很菜的，各位大佬别喷 www。
本题难度：入门代码中只有数组，没有逆置函数、指针等，请放心食用。（什）
题目现在输入数据，要求在输入前询问需要输入的数据个数，记为 n，接着接收这 n 个数据保存到数组中，然后输出逆置 (Reverse) 后的数组。
样例输入：513458

样例输出：你输入的数组：1 3 4 5 8逆置后数组：8 5 4 3 1

分析动态数组首先要求输入数据个数，那么直接 int 一个变量 n 再cin接收变量 n 即可。显然，数组长度是不确定的，所以我们需要用vector来创建一个动态数组。
#include &lt;vector&gt;vector&lt;int&gt; arr(n);
接着，循环 n 次来接收数组中的 n 个元素，可以直接使用 for 循环搞定，然后输出刚刚接收的所有元素即可。
元素交换我们假设第一个元素为start，最后一个元素为end。第一个元素为arr[0]，最后一个元素就是arr[n-1]（因为从 0 开始）。要逆置数组，只需要先取出第一个元素即arr[0] ，这里先 int 一个temp变量，然后将arr[0]放入temp变量中。接着，将最后一个元素即arr[n-1]覆盖到arr[0]的位置，最后再用temp覆盖掉arr[n-1]。这样就完成了首尾元素的交换。
循坏完成一次交换后，让start + 1，end - 1 ，这样就可以进行第二个元素和倒数第二个元素的位置交换，不难发现，在start &lt; end条件满足的情况下，循环将持续进行。通过 start++ 和 end– 来确保在交换每一对元素后，start 和 end 向中间靠拢，直到整个数组逆置完成。
全部完成后，输出新的数组即可。
代码（有注释）#include &lt;iostream&gt;#include &lt;vector&gt; // 引入头文件using namespace std;int main() &#123;    int n;    cout &lt;&lt; &quot;输入数组的大小：&quot;;    cin &gt;&gt; n;    vector&lt;int&gt; arr(n); // 创建动态数组    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; &quot;输入你的数据：&quot;;         cin &gt;&gt; arr[i]; // 循环 n 次，接收输入的数据    &#125;    cout &lt;&lt; &quot;你输入的数组：&quot; &lt;&lt; endl;    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;; // 输出输入的数组    &#125;    cout &lt;&lt; endl;    int start = 0;    int end = n - 1;    while (start &lt; end) &#123; // 数组逆置通解        int temp = arr[start];        arr[start] = arr[end];        arr[end] = temp;        start++;        end--;    &#125;    cout &lt;&lt; &quot;逆置后数组：&quot;  &lt;&lt; endl;    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;; // 输出新数组，\t用于对齐文本    &#125;    cout &lt;&lt; endl; // 换行    return 0;&#125;
代码（无注释）#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;int main() &#123;    int n;    cout &lt;&lt; &quot;输入数组的大小：&quot;;    cin &gt;&gt; n;    vector&lt;int&gt; arr(n);    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; &quot;输入你的数据：&quot;;         cin &gt;&gt; arr[i];    &#125;    cout &lt;&lt; &quot;你输入的数组：&quot; &lt;&lt; endl;    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;;    &#125;    cout &lt;&lt; endl;    int start = 0;    int end = n - 1;    while (start &lt; end) &#123;        int temp = arr[start];        arr[start] = arr[end];        arr[end] = temp;        start++;        end--;    &#125;    cout &lt;&lt; &quot;逆置后数组：&quot;  &lt;&lt; endl;    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;;    &#125;    cout &lt;&lt; endl;    return 0;&#125;
直接倒序输出#include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;int main() &#123;    int n;    cout &lt;&lt; &quot;输入数组的大小：&quot;;    cin &gt;&gt; n;    vector&lt;int&gt; arr(n);    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; &quot;输入你的数据：&quot;;         cin &gt;&gt; arr[i];    &#125;    cout &lt;&lt; &quot;你输入的数组：&quot; &lt;&lt; endl;    for (int i = 0; i &lt; n; i++) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;;    &#125;    cout &lt;&lt; endl;    cout &lt;&lt; &quot;逆置后数组：&quot;  &lt;&lt; endl;    for (int i = n - 1; i &gt;= 0; i--) &#123;         cout &lt;&lt; arr[i] &lt;&lt; &quot;\t&quot;;    &#125;    cout &lt;&lt; endl;    return 0;&#125;
END

一个简洁的SwiftUI主页设计。

 提示参阅 Apple Developer官方网站来了解各种视图。Building layouts with stack views

引入SwiftUI和嵌套视图ZStack。import SwiftUIstruct LocationView: View &#123;    var body: some View &#123;        ZStack &#123;        &#125;    &#125;&#125;       
引入垂直视图VStack，创建logo与标题。VStack&#123;   Text(&quot;I&quot;)       .font(.system(size: 80))   Text(&quot;Your text here&quot;)       .foregroundColor(.primary)       .font(.largeTitle)&#125;   
引入水平视图HStack,创建第一块圆角矩形并引入数据。HStack&#123;    VStack(alignment: .center) &#123;        Text(&quot;Text&quot;)            .foregroundColor(.primary)            .font(.system(size: 18, weight: .bold, design: .rounded))        Text(&quot;Text&quot;.uppercased())            .foregroundColor(.primary)            .font(.system(size: 12, weight: .regular, design: .rounded))    &#125;    Spacer()    VStack(alignment: .center) &#123;        Text(&quot;Text&quot;)            .foregroundColor(.primary)            .font(.system(size: 18, weight: .bold, design: .rounded))        Text(&quot;Text&quot;.uppercased())            .foregroundColor(.primary)            .font(.system(size: 12, weight: .regular, design: .rounded))    &#125;    Spacer()    VStack(alignment: .center) &#123;        Text(&quot;24岁&quot;)            .foregroundColor(.primary)            .font(.system(size: 18, weight: .bold, design: .rounded))        Text(&quot;年龄&quot;.uppercased())            .foregroundColor(.primary)            .font(.system(size: 12, weight: .regular, design: .rounded))    &#125;&#125;.padding().foregroundStyle(LinearGradient(colors: [.blue, .indigo], startPoint: .top, endPoint: .bottom)).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 12, style: .continuous))
创建第二块圆角矩形并引入数据VStack(alignment: .leading, spacing: 2) &#123;    Text(&quot;Your text here.&quot;.uppercased())        .font(.headline)        .foregroundColor(.primary)    HStack(alignment: .top, content: &#123;        Text(&quot;Your text here.&quot;)            .foregroundColor(.primary)            .font(.caption)            .multilineTextAlignment(.leading)            .frame(width: 300, height: 32)        Spacer()        Text(&quot;Text&quot;)            .foregroundColor(.primary)            .font(.system(size: 12, weight: .bold))    &#125;)    .padding(.vertical)    HStack &#123;        VStack(alignment: .center, content: &#123;            Text(&quot;Text&quot;)                .foregroundColor(.primary)                .font(.system(size: 24, weight: .bold, design: .rounded))            Text(&quot;Text&quot;.uppercased())                .foregroundColor(.primary)                .font(.system(size: 12, weight: .regular, design: .rounded))        &#125;)        Spacer()        VStack(alignment: .center, content: &#123;            Text(&quot;Text&quot;)                .font(.system(size: 24, weight: .bold, design: .rounded))                .foregroundColor(.green)            Text(&quot;Text&quot;.uppercased())                .foregroundColor(.primary)                .font(.system(size: 12, weight: .regular, design: .rounded))        &#125;)        Spacer()        VStack(alignment: .center, content: &#123;            Text(&quot;Text&quot;)                .foregroundColor(.primary)                .font(.system(size: 24, weight: .bold, design: .rounded))            Text(&quot;Text&quot;.uppercased())                .foregroundColor(.primary)                .font(.system(size: 12, weight: .regular, design: .rounded))        &#125;)    &#125;&#125;.padding().foregroundColor(Color.black.opacity(0.8)).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 20, style: .continuous))
底部小字Text(&quot;Your text here&quot;)    .foregroundColor(.primary)    .padding()    .foregroundStyle(.black)    .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 12, style: .continuous))
底部按钮Button(&quot;Button&quot;)&#123;&#125;.frame(width:100.0,height:50.0).background(.tint).foregroundColor(.white).cornerRadius(30.0).padding()

完成后再添加Preview，运行后即可看到效果。

完整代码import SwiftUIstruct LocationView: View &#123;    var body: some View &#123;        ZStack &#123;            VStack &#123;                Text(&quot;I&quot;)                    .font(.system(size: 80))                Text(&quot;Text&quot;)                    .foregroundColor(.primary)                    .font(.largeTitle)                HStack&#123;                    VStack(alignment: .center) &#123;                        Text(&quot;Text&quot;)                            .foregroundColor(.primary)                            .font(.system(size: 18, weight: .bold, design: .rounded))                        Text(&quot;Text&quot;.uppercased())                            .foregroundColor(.primary)                            .font(.system(size: 12, weight: .regular, design: .rounded))                    &#125;                    Spacer()                    VStack(alignment: .center) &#123;                        Text(&quot;Text&quot;)                            .foregroundColor(.primary)                            .font(.system(size: 18, weight: .bold, design: .rounded))                        Text(&quot;Text&quot;.uppercased())                            .foregroundColor(.primary)                            .font(.system(size: 12, weight: .regular, design: .rounded))                    &#125;                    Spacer()                    VStack(alignment: .center) &#123;                        Text(&quot;Text&quot;)                            .foregroundColor(.primary)                            .font(.system(size: 18, weight: .bold, design: .rounded))                        Text(&quot;Text&quot;.uppercased())                            .foregroundColor(.primary)                            .font(.system(size: 12, weight: .regular, design: .rounded))                    &#125;                &#125;                .padding()                .foregroundStyle(LinearGradient(colors: [.blue, .indigo], startPoint: .top, endPoint: .bottom))                .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 12, style: .continuous))                VStack(alignment: .leading, spacing: 2) &#123;                    Text(&quot;Text&quot;.uppercased())                        .font(.headline)                        .foregroundColor(.primary)                    HStack(alignment: .top, content: &#123;                        Text(&quot;Your text here.&quot;)                            .foregroundColor(.primary)                            .font(.caption)                            .multilineTextAlignment(.leading)                            .frame(width: 300, height: 32)                        Spacer()                        Text(&quot;Text&quot;)                            .foregroundColor(.primary)                            .font(.system(size: 12, weight: .bold))                    &#125;)                    .padding(.vertical)                    HStack &#123;                        VStack(alignment: .center, content: &#123;                            Text(&quot;Text&quot;)                                .foregroundColor(.primary)                                .font(.system(size: 24, weight: .bold, design: .rounded))                            Text(&quot;Text&quot;.uppercased())                                .foregroundColor(.primary)                                .font(.system(size: 12, weight: .regular, design: .rounded))                        &#125;)                        Spacer()                        VStack(alignment: .center, content: &#123;                            Text(&quot;Text&quot;)                                .font(.system(size: 24, weight: .bold, design: .rounded))                                .foregroundColor(.green)                            Text(&quot;Text&quot;.uppercased())                                .foregroundColor(.primary)                                .font(.system(size: 12, weight: .regular, design: .rounded))                        &#125;)                        Spacer()                        VStack(alignment: .center, content: &#123;                            Text(&quot;Text&quot;)                                .foregroundColor(.primary)                                .font(.system(size: 24, weight: .bold, design: .rounded))                            Text(&quot;Text&quot;.uppercased())                                .foregroundColor(.primary)                                .font(.system(size: 12, weight: .regular, design: .rounded))                        &#125;)                    &#125;                &#125;                .padding()                .foregroundColor(Color.black.opacity(0.8))                .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 20, style: .continuous))                Text(&quot;Your text here.&quot;)                    .foregroundColor(.primary)                    .padding()                    .foregroundStyle(.black)                    .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 12, style: .continuous))                Button(&quot;Button&quot;)&#123;                &#125;                .frame(width:100.0,height:50.0)                .background(.tint)                .foregroundColor(.white)                .cornerRadius(30.0)                .padding()            &#125;        &#125;    &#125;        struct LocationView_Previews: PreviewProvider &#123;        static var previews: some View &#123;            LocationView()        &#125;    &#125;&#125;
